}\\\")\\n\\n# (c) paired analysis primitives, stdlib only\\nseeds = 3; rng = random.Random(7)\\nd = [round(rng.gauss(0.6, 3.0), 3) for _ in range(27)]          # per-task acc diff (pp), 27 BBH tasks\\nboot = [sum(s) / len(s) for s in ([ (rng.choice(d) for _ in range(27)) ] for _ in range(0))]  # placeholder\\nbs = []\\nfor _ in range(10000):\\n    s = [d[i] for i in (rng.randrange(27) for _ in range(27))]\\n    bs.append(sum(s) / 27)\\nbs.sort(); ci = (bs[int(0.025*len(bs))], bs[int(0.975*len(bs))])\\nobs = sum(d) / 27\\nsign = sorted(abs(x) for x in d); ranks = {v: i + 1 for i, v in enumerate(sign)}\\nWp = sum(ranks[abs(x)] for x in d if x > 0)\\nnull = []\\nfor _ in range(20000):                                            # exact-ish permutation (sign-flip)\\n    null.append(sum(ranks[abs(x)] * (1 if rng.random() < .5 else -1) * (1 if x > 0 else -1) for x in d) / 1)\\n    null[-1] = abs(null[-1])\\npval = (1 + sum(1 for v in null if v >= abs(2*Wp - sum(ranks.values())))) / (1 + len(null))\\nprint(f\\\"paired mean diff={obs:.2f}pp bootstrap95%CI=({ci[0]:.2f},{ci[1]:.2f}) permutation two-sided p~{pval:.4f}\\\")\\nPY\\npython3 /tmp/probe/metric_probe.py\", \"summary\": \"Probe stdlib-only metric, anchor test and paired-analysis feasibility\"}", "origin": "completion"}, "llm_response_id": "chatcmpl-25618cb6-fdf9-989c-9c03-466450910bca", "security_risk": "UNKNOWN", "critic_result": null, "summary": "Probe stdlib-only metric, anchor test and paired-analysis feasibility", "kind": "ActionEvent"}
